@inlinable
public func max<Scalar: Comparable>(_ e1: Vector4<Scalar>, _ e2: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(Swift.max(e1.x, e2.x), Swift.max(e1.y, e2.y), Swift.max(e1.z, e2.z), Swift.max(e1.w, e2.w))
}

/// Each component of `e`, limited to the range from `low` to `high`.
@inlinable
public func clamp<Scalar: Comparable>(_ e: Vector4<Scalar>, _ low: Vector4<Scalar>, _ high: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(clamp(e.x, low.x, high.x), clamp(e.y, low.y, high.y), clamp(e.z, low.z, high.z), clamp(e.w, low.w, high.w))
}

/// Each component rounded down.
@inlinable
public func floor<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(e.x.rounded(.down), e.y.rounded(.down), e.z.rounded(.down), e.w.rounded(.down))
}

/// Each component rounded up.
@inlinable
public func ceil<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(e.x.rounded(.up), e.y.rounded(.up), e.z.rounded(.up), e.w.rounded(.up))
}

/// Each component rounded to the nearest integer, ties to even.
@inlinable
public func round<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(e.x.rounded(.toNearestOrEven), e.y.rounded(.toNearestOrEven), e.z.rounded(.toNearestOrEven), e.w.rounded(.toNearestOrEven))
}

/// Each component rounded toward zero.
@inlinable
public func trunc<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(e.x.rounded(.towardZero), e.y.rounded(.towardZero), e.z.rounded(.towardZero), e.w.rounded(.towardZero))
}

/// The fractional part of each component, `e - floor(e)`.
@inlinable
public func fract<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(fract(e.x), fract(e.y), fract(e.z), fract(e.w))
}

/// The square root of each component.
@inlinable
public func sqrt<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(e.x.squareRoot(), e.y.squareRoot(), e.z.squareRoot(), e.w.squareRoot())
}

/// The reciprocal of the square root of each component.
@inlinable
public func inverseSqrt<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(inverseSqrt(e.x), inverseSqrt(e.y), inverseSqrt(e.z), inverseSqrt(e.w))
}

/// Each component limited to the range from 0 to 1.
@inlinable
public func saturate<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(saturate(e.x), saturate(e.y), saturate(e.z), saturate(e.w))
}

/// Each component converted from radians to degrees.
@inlinable
public func degrees<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(degrees(e.x), degrees(e.y), degrees(e.z), degrees(e.w))
}

/// Each component converted from degrees to radians.
@inlinable
public func radians<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(radians(e.x), radians(e.y), radians(e.z), radians(e.w))
}

/// 1 for each component of `x` at or above `edge`, and 0 elsewhere.
@inlinable
public func step<Scalar: FloatingPoint>(_ edge: Vector4<Scalar>, _ x: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(step(edge.x, x.x), step(edge.y, x.y), step(edge.z, x.z), step(edge.w, x.w))
}

/// Each component of `x` mapped smoothly from the range from `low` to `high` onto 0 to 1.
@inlinable
public func smoothstep<Scalar: FloatingPoint>(_ low: Vector4<Scalar>, _ high: Vector4<Scalar>, _ x: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(smoothstep(low.x, high.x, x.x), smoothstep(low.y, high.y, x.y), smoothstep(low.z, high.z, x.z), smoothstep(low.w, high.w, x.w))
}

/// `e1 * e2 + e3` for each component, rounded once.
@inlinable
public func fma<Scalar: FloatingPoint>(_ e1: Vector4<Scalar>, _ e2: Vector4<Scalar>, _ e3: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(e3.x.addingProduct(e1.x, e2.x), e3.y.addingProduct(e1.y, e2.y), e3.z.addingProduct(e1.z, e2.z), e3.w.addingProduct(e1.w, e2.w))
}

/// The linear blend of `e1` and `e2` by each component of `e3`.
@inlinable
public func mix<Scalar: FloatingPoint>(_ e1: Vector4<Scalar>, _ e2: Vector4<Scalar>, _ e3: Vector4<Scalar>) -> Vector4<Scalar> {
    Vector4(mix(e1.x, e2.x, e3.x), mix(e1.y, e2.y, e3.y), mix(e1.z, e2.z, e3.z), mix(e1.w, e2.w, e3.w))
}

/// The linear blend of `e1` and `e2` by `e3`.
@inlinable
public func mix<Scalar: FloatingPoint>(_ e1: Vector4<Scalar>, _ e2: Vector4<Scalar>, _ e3: Scalar) -> Vector4<Scalar> {
    Vector4(mix(e1.x, e2.x, e3), mix(e1.y, e2.y, e3), mix(e1.z, e2.z, e3), mix(e1.w, e2.w, e3))
}

// MARK: - Geometric built-in functions

/// The dot product of `e1` and `e2`.
@inlinable
public func dot<Scalar: Numeric>(_ e1: Vector4<Scalar>, _ e2: Vector4<Scalar>) -> Scalar {
    var result = e1.x * e2.x
    result += e1.y * e2.y
    result += e1.z * e2.z
    result += e1.w * e2.w
    return result
}

/// The length of `e`.
@inlinable
public func length<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Scalar {
    dot(e, e).squareRoot()
}

/// The distance between `e1` and `e2`.
@inlinable
public func distance<Scalar: FloatingPoint>(_ e1: Vector4<Scalar>, _ e2: Vector4<Scalar>) -> Scalar {
    length(e1 - e2)
}

/// `e` scaled to a length of 1. The result is not finite when `e` is zero.
@inlinable
public func normalize<Scalar: FloatingPoint>(_ e: Vector4<Scalar>) -> Vector4<Scalar> {
    e / length(e)
}

/// `e1` if `e2` points away from `e3`, and `-e1` otherwise.
@inlinable
public func faceForward<Scalar: FloatingPoint>(_ e1: Vector4<Scalar>, _ e2: Vector4<Scalar>, _ e3: Vector4<Scalar>) -> Vector4<Scalar> {
    dot(e2, e3) < 0 ? e1 : -e1
}

/// The reflection of the incident direction `e1` off a surface with normal `e2`.
@inlinable
public func reflect<Scalar: FloatingPoint>(_ e1: Vector4<Scalar>, _ e2: Vector4<Scalar>) -> Vector4<Scalar> {
    let scale: Scalar = 2 * dot(e2, e1)
    return e1 - e2 * scale
}

/// The refraction of the incident direction `e1` through a surface with normal
/// `e2`, for the ratio of indices of refraction `e3`. Zero on total internal
/// reflection.
@inlinable
public func refract<Scalar: FloatingPoint>(_ e1: Vector4<Scalar>, _ e2: Vector4<Scalar>, _ e3: Scalar) -> Vector4<Scalar> {
    let cosine: Scalar = dot(e2, e1)
    let k: Scalar = 1 - e3 * e3 * (1 - cosine * cosine)
    guard k >= 0 else {
        return .zero
    }
    let scale: Scalar = e3 * cosine + k.squareRoot()
    return e1 * e3 - e2 * scale
}
